sys_script_include.script:
var MetroFareAjax = Class.create();

MetroFareAjax.prototype = Object.extendsObject(
    global.AbstractAjaxProcessor,
    {

        calculateFare: function() {

            var sourceId =
                this.getParameter(
                    'sysparm_source'
                );

            var destinationId =
                this.getParameter(
                    'sysparm_destination'
                );

            var journeyType =
                this.getParameter(
                    'sysparm_journey_type'
                );

            var passengerCount =
                this.getParameter(
                    'sysparm_passengers'
                );


            var service =
                new MetroFareService();


            var result =
                service.calculateFare(
                    sourceId,
                    destinationId,
                    journeyType,
                    passengerCount
                );


            return JSON.stringify(
                result
            );
        },


        type: 'MetroFareAjax'
    }
);
